// ReactMemoryProfiler.js
class ReactMemoryProfiler {
  constructor(options = {}) {
    this.options = {
      checkInterval: options.checkInterval || 10000, // 10s
      growthThreshold: options.growthThreshold || 1.15, // 15% growth
      ...options
    };

    this.history = [];
    this.registry = null;
    this.activeComponents = new Map();
    this.isMonitoring = false;

    this.initGarbageCollectionTracker();
  }

  // 1. Track if unmounted components are actually Garbage Collected
  initGarbageCollectionTracker() {
    if (typeof FinalizationRegistry !== 'undefined') {
      this.registry = new FinalizationRegistry((info) => {
        console.log(`[MemoryProfiler] Cleaned from memory: ${info.componentName}`);
        this.activeComponents.delete(info.id);
      });
    } else {
      console.warn("FinalizationRegistry not supported in this environment.");
    }
  }

  // Hook into React Component Lifecycle
  trackMount(componentName, instance) {
    const id = `${componentName}_${Math.random().toString(36).substr(2, 9)}`;
    const componentInfo = {
      id,
      componentName,
      mountedAt: performance.now(),
      listenersCount: this.countEventListeners(instance)
    };

    this.activeComponents.set(id, componentInfo);
    return id;
  }

  trackUnmount(id, componentName) {
    const info = this.activeComponents.get(id);
    if (info && this.registry) {
      // Hold a weak reference. If GC doesn't clear this after 15 seconds, it's a leak!
      const target = { leakedComponent: componentName };
      this.registry.register(target, { componentName, id, unmountedAt: performance.now() });

      setTimeout(() => {
        // If it's still tracked by our registry logic implicitly, flag it
        if (this.activeComponents.has(id)) {
          this.reportLeak(componentName, 'Potential Lifecycle Leak / Retained Reference');
        }
      }, 15000); 
    }
  }

  // 2. Trend Analysis Algorithm (Detect continuous growth)
  async sampleMemory() {
    if (!performance.memory && !performance.measureUserAgentSpecificMemory) {
      return;
    }

    let usedHeap = 0;
    if (performance.measureUserAgentSpecificMemory) {
      const sample = await performance.measureUserAgentSpecificMemory();
      usedHeap = sample.bytes;
    } else {
      usedHeap = performance.memory.usedJSHeapSize;
    }

    const timestamp = performance.now();
    this.history.push({ timestamp, usedHeap, detachedDOMCount: this.getDetachedDOMCount() });

    if (this.history.length > 5) {
      this.analyzeTrends();
    }
  }

  analyzeTrends() {
    const recent = this.history.slice(-5);
    let continuousGrowth = true;

    for (let i = 1; i < recent.length; i++) {
      if (recent[i].usedHeap <= recent[i - 1].usedHeap) {
        continuousGrowth = false;
        break;
      }
    }

    if (continuousGrowth) {
      const totalGrowth = recent[recent.length - 1].usedHeap / recent[0].usedHeap;
      if (totalGrowth >= this.options.growthThreshold) {
        this.suggestOptimizations('Continuous Heap Growth Detected');
      }
    }
  }

  // 3. Analyze Detached DOM elements
  getDetachedDOMCount() {
    // Basic heuristic: query nodes not attached to document body
    // In production tooling, this interacts with Chrome DevTools Protocol (CDP)
    return document.querySelectorAll('*').length - document.body.querySelectorAll('*').length;
  }

  countEventListeners(instance) {
    // Fallback heuristic for tracking standard event registrations
    if (!instance) return 0;
    return Object.keys(instance).filter(key => key.startsWith('on')).length;
  }

  reportLeak(componentName, type) {
    console.error(`🚨 [MEMORY LEAK] Component "${componentName}" failed to garbage collect. Type: ${type}`);
  }

  // 4. Automated Pattern Suggestion Engine
  suggestOptimizations(reason) {
    console.warn(`💡 [Memory Optimizer Suggestion]: ${reason}`);
    console.table([
      { Pattern: 'Uncleared useEffect setInterval/setTimeout', Fix: 'Return a cleanup function clearing the timer.' },
      { Pattern: 'Global Event Listeners', Fix: 'Ensure window.removeEventListener is called on unmount.' },
      { Pattern: 'Detached DOM Reference', Fix: 'Avoid saving direct DOM node references inside global states or closures.' }
    ]);
  }

  start() {
    if (this.isMonitoring) return;
    this.isMonitoring = true;
    this.intervalId = setInterval(() => this.sampleMemory(), this.options.checkInterval);
  }

  stop() {
    clearInterval(this.intervalId);
    this.isMonitoring = false;
  }
}

export const memoryProfiler = new ReactMemoryProfiler();      Step 1: The Core Memory Leak Detector Utility (ReactMemoryProfiler.js)
This utility monitors component mounts/unmounts, uses a FinalizationRegistry to detect if unmounted components are being held in memory (garbage collection failures), and tracks event listener counts
